<?php
declare(strict_types=1);

http_response_code(404);
require_once __DIR__ . '/includes/auth.php';
startSession();

$basePath = rtrim(str_replace('\\', '/', dirname((string) ($_SERVER['SCRIPT_NAME'] ?? ''))), '/');
$assetUrl = $basePath . '/assets/images/404.png';
$roleId = (int) ($_SESSION['role_id'] ?? 0);
$roleName = strtolower(trim((string) ($_SESSION['role_name'] ?? '')));
$homeUrl = $basePath . '/login.php';
if (isLoggedIn()) {
    if ($roleId === 1 || $roleName === 'admin') $homeUrl = $basePath . '/pages/admin/dashboard.php';
    elseif ($roleName === 'petugas' || $roleId === 2) $homeUrl = $basePath . '/pages/petugas/dashboard.php';
    elseif ($roleName === 'visitor' || $roleId === 3) $homeUrl = $basePath . '/pages/visitor/dashboard.php';
    elseif ($roleName === 'pimpinan' || $roleId === 4) $homeUrl = $basePath . '/pages/pimpinan/dashboard.php';
}
?>
